import{_ as r,o as l,c as t,a3 as i,j as e,a}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/schueler/einwilligung-01.png",s="/bilder/schueler/einwilligung-02.png",f=JSON.parse('{"title":"Einwilligungen und Lernplattform-Zustimmungen verwalten","description":"","frontmatter":{"title":"Einwilligungen und Lernplattform-Zustimmungen verwalten","source_pageid":596,"source_revision":5751},"headers":[],"relativePath":"schild3/schueler/einwilligung-schueler.md","filePath":"schild3/schueler/einwilligung-schueler.md"}'),g={name:"schild3/schueler/einwilligung-schueler.md"};function d(o,n,h,c,p,m){return l(),t("div",null,[...n[0]||(n[0]=[i('<h1 id="einwilligungen-und-lernplattform-zustimmungen-verwalten" tabindex="-1">Einwilligungen und Lernplattform-Zustimmungen verwalten <a class="header-anchor" href="#einwilligungen-und-lernplattform-zustimmungen-verwalten" aria-label="Permalink to &quot;Einwilligungen und Lernplattform-Zustimmungen verwalten&quot;">​</a></h1><p>Dokumentieren Sie für einzelne Schülerinnen und Schüler die Abfrage und Zustimmung zu Einwilligungen und Lernplattformen. Die Einträge müssen zuvor in den Katalogen angelegt sein.</p><p>In diesem Reiter können für die ausgewählte Schülerin bzw. den ausgewählten Schüler die Einwilligungen sowohl in die Nutzung personenbezogener Daten gemäß DSGVO als auch zur Nutzung von Lernplattformen verwaltet werden.</p><p>Beide Arten von Einwilligungen werden unter den (schulbezogenen) Katalogen verwaltet. Erst danach können sie hier für die ausgewählten Schülerinnen und Schülern bearbeitet werden.</p><h2 id="individuelle-schulerinnen-und-schuler" tabindex="-1">Individuelle Schülerinnen und Schüler <a class="header-anchor" href="#individuelle-schulerinnen-und-schuler" aria-label="Permalink to &quot;Individuelle Schülerinnen und Schüler&quot;">​</a></h2><h3 id="einwilligungen" tabindex="-1">Einwilligungen <a class="header-anchor" href="#einwilligungen" aria-label="Permalink to &quot;Einwilligungen&quot;">​</a></h3><p><a href="/bilder/schueler/einwilligung-01.png"><img src="'+u+'" alt="Bearbeitung der Einwilligung für einzelne Schülerinnen und Schüler unter Schüler ➜ Einwilligung." loading="lazy"></a></p><p><em>Bearbeitung der Einwilligung für einzelne Schülerinnen und Schüler unter Schüler ➜ Einwilligung.</em></p><p>Für die in den Katalogen angelegten DSGVO-Einwilligungen kann hier durch Setzen eines Hakens angewählt werden, ob das entsprechende Kriterium bereits abgefragt wurde. Die Nutzung dieses Hakens ist insbesondere für neue Schülerinnen und Schüler sinnvoll, da so fehlende Abfragen schnell gefunden werden können.</p><p>Setzen Sie <strong>Zustimmung</strong> nur, wenn eine entsprechende Einwilligung vorliegt; <strong>Abgefragt</strong> dokumentiert allein die Abfrage. Der Dateneintrag ersetzt den Einwilligungsnachweis nicht. Für die Schülerdaten ist <a href="https://bass.schule.nrw/101.htm" target="_blank" rel="noreferrer">§ 3 Absatz 2 VO-DV I</a> maßgeblich.</p>',10),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),a("Tipp")]),e("p",null,"Der Reiter kann auch zur Verwaltung von Einwilligungen verwendet werden, die nicht mit der DSGVO zusammenhängen.")],-1),i('<h3 id="lernplattformen" tabindex="-1">Lernplattformen <a class="header-anchor" href="#lernplattformen" aria-label="Permalink to &quot;Lernplattformen&quot;">​</a></h3><p>Ebenso wie für die Einwilligungen kann auch für die von der Schule verwendeten Lernplattformen die individuelle Einwilligung verwaltet werden. Die Einrichtung einer Lernplattform und die dafür angebotenen Exporte sind gesonderte Arbeitsschritte. Verwenden Sie dafür die zum jeweiligen Verfahren gehörende Anleitung; die Einwilligungsansicht allein richtet kein Benutzerkonto ein.</p><h2 id="gruppenprozesse" tabindex="-1">Gruppenprozesse <a class="header-anchor" href="#gruppenprozesse" aria-label="Permalink to &quot;Gruppenprozesse&quot;">​</a></h2><p><a href="/bilder/schueler/einwilligung-02.png"><img src="'+s+'" alt="Bearbeitung der Einwilligung für Schülerinnen und Schüler per Gruppenprozess." loading="lazy"></a></p><p><em>Bearbeitung der Einwilligung für Schülerinnen und Schüler per Gruppenprozess.</em></p><p>Für zuvor ausgewählte Klassen, Jahrgänge oder andere Gruppen können Sie die Angaben per Gruppenprozess setzen. Ändern Sie <strong>Abgefragt</strong> und <strong>Zustimmung</strong> getrennt; mit <strong>keine Änderung</strong> bleibt die jeweilige bestehende Angabe erhalten. Markieren Sie für eine gemeinsame Zustimmung nur Personen, für die tatsächlich der entsprechende Nachweis vorliegt.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Einwilligung_(Sch%C3%BCler)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5751.</p>',8)])])}const b=r(g,[["render",d]]);export{f as __pageData,b as default};
